BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS coaching_tenants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS coaching_identities(tenant_id uuid NOT NULL REFERENCES coaching_tenants(id),subject text NOT NULL,role text NOT NULL CHECK(role IN('client','coach','operator')),email text,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,subject));
CREATE TABLE IF NOT EXISTS coach_profiles(tenant_id uuid NOT NULL REFERENCES coaching_tenants(id),coach_subject text NOT NULL,specialties text[] NOT NULL DEFAULT '{}',capacity integer NOT NULL DEFAULT 10 CHECK(capacity>=0),active boolean NOT NULL DEFAULT true,PRIMARY KEY(tenant_id,coach_subject));
CREATE TABLE IF NOT EXISTS coaching_engagements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES coaching_tenants(id),client_subject text NOT NULL,coach_subject text NOT NULL,state text NOT NULL DEFAULT 'PENDING_PAYMENT',program_name text NOT NULL,price_cents integer NOT NULL CHECK(price_cents>0),currency char(3) NOT NULL DEFAULT 'USD',idempotency_key text NOT NULL,version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,client_subject,idempotency_key));
CREATE TABLE IF NOT EXISTS coaching_goals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES coaching_tenants(id),engagement_id uuid NOT NULL REFERENCES coaching_engagements(id),title text NOT NULL,outcome_metric text NOT NULL,target_value text NOT NULL,target_date date,status text NOT NULL DEFAULT 'ACTIVE' CHECK(status IN('ACTIVE','ACHIEVED','ARCHIVED')),progress integer NOT NULL DEFAULT 0 CHECK(progress BETWEEN 0 AND 100),version integer NOT NULL DEFAULT 1,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS coaching_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES coaching_tenants(id),engagement_id uuid NOT NULL REFERENCES coaching_engagements(id),starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,state text NOT NULL DEFAULT 'VIDEO_PENDING',meeting_url text,provider_meeting_id text,agenda text NOT NULL,coach_notes text,client_reflection text,version integer NOT NULL DEFAULT 1,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(ends_at>starts_at));
CREATE TABLE IF NOT EXISTS coaching_action_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES coaching_tenants(id),session_id uuid NOT NULL REFERENCES coaching_sessions(id),owner_subject text NOT NULL,title text NOT NULL,due_date date,status text NOT NULL DEFAULT 'OPEN' CHECK(status IN('OPEN','DONE','CANCELLED')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS coaching_check_ins(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES coaching_tenants(id),goal_id uuid NOT NULL REFERENCES coaching_goals(id),progress integer NOT NULL CHECK(progress BETWEEN 0 AND 100),evidence text NOT NULL,confidence integer CHECK(confidence BETWEEN 1 AND 5),created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS coaching_provider_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES coaching_tenants(id),engagement_id uuid REFERENCES coaching_engagements(id),session_id uuid REFERENCES coaching_sessions(id),provider text NOT NULL CHECK(provider IN('billing','video','notification')),operation text NOT NULL,idempotency_key text NOT NULL,request_payload jsonb NOT NULL,response_payload jsonb,status text NOT NULL DEFAULT 'queued' CHECK(status IN('queued','running','succeeded','retryable','dead-letter')),attempts integer NOT NULL DEFAULT 0,next_attempt_at timestamptz NOT NULL DEFAULT now(),last_error_code text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,provider,idempotency_key));
CREATE TABLE IF NOT EXISTS coaching_webhook_receipts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES coaching_tenants(id),provider text NOT NULL,delivery_id text NOT NULL,body_sha256 text NOT NULL,received_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,provider,delivery_id));
CREATE TABLE IF NOT EXISTS coaching_restore_drills(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES coaching_tenants(id),backup_reference text NOT NULL,status text NOT NULL CHECK(status IN('scheduled','passed','failed')),evidence_uri text,recorded_by text NOT NULL,recorded_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS coaching_audit_events(sequence bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES coaching_tenants(id),actor_subject text NOT NULL,action text NOT NULL,resource_type text NOT NULL,resource_id uuid,from_state text,to_state text,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,occurred_at timestamptz NOT NULL DEFAULT now());
CREATE OR REPLACE FUNCTION reject_coaching_audit_mutation()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'coaching audit is append-only';END;$$;
DROP TRIGGER IF EXISTS coaching_audit_immutable ON coaching_audit_events;
CREATE TRIGGER coaching_audit_immutable BEFORE UPDATE OR DELETE ON coaching_audit_events FOR EACH ROW EXECUTE FUNCTION reject_coaching_audit_mutation();
CREATE INDEX IF NOT EXISTS coaching_engagement_actor_idx ON coaching_engagements(tenant_id,client_subject,coach_subject,created_at DESC);
CREATE INDEX IF NOT EXISTS coaching_sessions_engagement_idx ON coaching_sessions(tenant_id,engagement_id,starts_at DESC);
CREATE INDEX IF NOT EXISTS coaching_jobs_due_idx ON coaching_provider_jobs(status,next_attempt_at);
COMMIT;
